def calc(f,n):
    m=2+n;g=10;v=4+n;h=5+n;t=4+n;force=12+n*3;s=3+n;eta=F(4+n,20)
    if f=='horizontal-work':
        r=force*s;return f'সরলপথে সরণের দিকেই {force} N ধ্রুব বল {s} m সরণ ঘটায়। এই বলের কাজ কত?',r,' J',f'W = Fs = {force}×{s} = {r} J।',dict(force=force,s=s)
    if f=='lift-work':
        r=m*g*h;return f'{m} kg বস্তুকে সমবেগে {h} m ওপরে তোলা হয়। g = 10 m/s², ক্ষয় নেই। উত্তোলন বলের কাজ কত?',r,' J',f'W = mgh = {m}×10×{h} = {r} J।',dict(m=m,g=g,h=h)
    if f=='distance':
        work=force*s;r=F(work,force);return f'{force} N ধ্রুব বল নিজের দিকে {work} J কাজ করে। সরণ কত?',r,' m',f's = W/F = {work}/{force} = {fmt(r)} m।',dict(work=work,force=force)
    if f=='force':
        work=force*s;r=F(work,s);return f'সরণের দিকের ধ্রুব বল {s} m পথে {work} J কাজ করে। বলের মান কত?',r,' N',f'F = W/s = {work}/{s} = {fmt(r)} N।',dict(work=work,s=s)
    if f=='power':
        work=180+n*60;r=F(work,t);return f'এক যন্ত্র {t} s-এ {work} J কাজ করে। গড় ক্ষমতা কত?',r,' W',f'P = W/t = {work}/{t} = {fmt(r)} W।',dict(work=work,t=t)
    if f=='time':
        power=30+n*10;work=power*t;r=F(work,power);return f'{power} W ধ্রুব উপযোগী ক্ষমতার যন্ত্রে {work} J উপযোগী কাজ করতে সময় কত?',r,' s',f't = W/P = {work}/{power} = {fmt(r)} s।',dict(work=work,power=power)
    if f=='energy-pt':
        power=25+n*5;r=power*t;return f'{power} W ধ্রুব হারে শক্তি গ্রহণকারী যন্ত্র {t} s চলে। গৃহীত শক্তি কত?',r,' J',f'E = Pt = {power}×{t} = {r} J।',dict(power=power,t=t)
    if f=='lift-power':
        r=F(m*g*h,t);return f'{m} kg ভার সমবেগে {h} m ওপরে তুলতে {t} s লাগে। g = 10 m/s² ও ক্ষয় নেই। গড় উপযোগী ক্ষমতা কত?',r,' W',f'P = mgh/t = {m}×10×{h}/{t} = {fmt(r)} W।',dict(m=m,g=g,h=h,t=t)
    if f=='lift-mass':
        t=2*h;power=F(m*g*h,t);r=F(m);return f'ক্ষয়হীন উত্তোলকে {fmt(power)} W উপযোগী ক্ষমতায় {t} s-এ ভার {h} m সমবেগে ওঠে। g = 10 m/s²। ভর কত?',r,' kg',f'm = Pt/(gh) = {fmt(power)}×{t}/(10×{h}) = {fmt(r)} kg।',dict(power=power,t=t,g=g,h=h)
    if f=='kinetic':
        r=F(m*v*v,2);return f'{m} kg বস্তুর দ্রুতি {v} m/s। চলন গতিশক্তি কত?',r,' J',f'Eₖ = ½mv² = ½×{m}×{v}² = {fmt(r)} J।',dict(m=m,v=v)
    if f=='speed-ke':
        energy=F(m*v*v,2);r=F(v);return f'{m} kg বস্তুর চলন গতিশক্তি {fmt(energy)} J। দ্রুতি কত?',r,' m/s',f'v² = 2Eₖ/m = {v*v}; v = {v} m/s।',dict(m=m,energy=energy)
    if f=='mass-ke':
        energy=F(m*v*v,2);r=F(m);return f'{v} m/s দ্রুতির বস্তুর চলন গতিশক্তি {fmt(energy)} J। ভর কত?',r,' kg',f'm = 2Eₖ/v² = 2×{fmt(energy)}/{v}² = {m} kg।',dict(v=v,energy=energy)
    if f=='potential':
        r=m*g*h;return f'নির্বাচিত শূন্যস্তরের {h} m ওপরে {m} kg বস্তু আছে। g = 10 m/s²। বিভবশক্তি কত?',r,' J',f'Eₚ = mgh = {m}×10×{h} = {r} J।',dict(m=m,g=g,h=h)
    if f=='height-pe':
        energy=m*g*h;r=F(h);return f'{m} kg বস্তুর মহাকর্ষীয় বিভবশক্তি {energy} J, g = 10 m/s²। নির্দিষ্ট শূন্যস্তর থেকে উচ্চতা কত?',r,' m',f'h = Eₚ/(mg) = {energy}/({m}×10) = {h} m।',dict(m=m,g=g,energy=energy)
    if f=='mass-pe':
        energy=m*g*h;r=F(m);return f'শূন্যস্তরের {h} m ওপরে বিভবশক্তি {energy} J। g = 10 m/s² হলে ভর কত?',r,' kg',f'm = Eₚ/(gh) = {energy}/(10×{h}) = {m} kg।',dict(h=h,g=g,energy=energy)
    if f=='efficiency':
        inp=1000+n*200;out=eta*inp;r=eta*100;return f'এক যন্ত্র {inp} J ইনপুট থেকে {fmt(out)} J উপযোগী আউটপুট দেয়। শতকরা কর্মদক্ষতা কত?',r,'%',f'η = Eউপযোগী/Eইন ×100 = {fmt(out)}/{inp}×100 = {fmt(r)}%।',dict(inp=inp,out=out)
    if f=='useful-energy':
        inp=1200+n*200;r=eta*inp;return f'এক যন্ত্রে ইনপুট {inp} J, কর্মদক্ষতা {fmt(eta*100)}%। উপযোগী শক্তি কত?',r,' J',f'Eউপযোগী = ηEইন = {fmt(eta)}×{inp} = {fmt(r)} J।',dict(inp=inp,percent=eta*100)
    if f=='input-energy':
        out=200+n*60;r=F(out)/eta;return f'{fmt(eta*100)}% দক্ষ যন্ত্রে {out} J উপযোগী শক্তি পেতে ইনপুট কত?',r,' J',f'Eইন = Eউপযোগী/η = {out}/{fmt(eta)} = {fmt(r)} J।',dict(out=out,percent=eta*100)
    if f=='useful-power':
        inp=500+n*100;r=eta*inp;return f'যন্ত্রের ধ্রুব ইনপুট ক্ষমতা {inp} W ও দক্ষতা {fmt(eta*100)}%। উপযোগী আউটপুট ক্ষমতা কত?',r,' W',f'Pউপযোগী = ηPইন = {fmt(eta)}×{inp} = {fmt(r)} W।',dict(inp=inp,percent=eta*100)
    if f=='input-power':
        out=100+n*40;r=F(out)/eta;return f'{fmt(eta*100)}% দক্ষ মোটরের উপযোগী আউটপুট {out} W। ইনপুট ক্ষমতা কত?',r,' W',f'Pইন = Pউপযোগী/η = {out}/{fmt(eta)} = {fmt(r)} W।',dict(out=out,percent=eta*100)
    if f=='kwh-joule':
        energy=F(2+n,2);r=energy*3600000;return f'{fmt(energy)} kWh শক্তি কত J?',r,' J',f'1 kWh = 3600000 J; শক্তি = {fmt(energy)}×3600000 = {fmt(r)} J।',dict(energy=energy)
    if f=='kw-watt':
        power=F(3+n,4);r=power*1000;return f'এক যন্ত্রের ক্ষমতা {fmt(power)} kW। W এককে কত?',r,' W',f'1 kW = 1000 W; {fmt(power)}×1000 = {fmt(r)} W।',dict(power=power)
    if f=='mechanical-total':
        r=F(m*v*v,2)+m*g*h;return f'{m} kg বস্তুর দ্রুতি {v} m/s, শূন্যস্তর থেকে উচ্চতা {h} m, g = 10 m/s²। মোট যান্ত্রিক শক্তি কত?',r,' J',f'E = ½mv²+mgh = {fmt(F(m*v*v,2))}+{m*g*h} = {fmt(r)} J।',dict(m=m,v=v,g=g,h=h)
    if f=='fall-ke':
        r=m*g*h;return f'{m} kg বস্তু স্থির থেকে {h} m নিচে নামে। শুধু মহাকর্ষ কাজ করে, g = 10 m/s²। নামার শেষে গতিশক্তি কত?',r,' J',f'বিভবশক্তির হ্রাস = mgh = {m}×10×{h} = {r} J, যা গতিশক্তি হয়েছে।',dict(m=m,g=g,h=h)
    if f=='fall-speed':
        v=10+n*2;h=F(v*v,20);r=F(v);return f'স্থির থেকে {fmt(h)} m বাধাহীন পতনে শেষ দ্রুতি কত? g = 10 m/s²।',r,' m/s',f'½mv² = mgh; v² = 2×10×{fmt(h)} = {v*v}, তাই v = {v} m/s।',dict(h=h,g=g)
    if f=='rise-height':
        v=10+n*2;r=F(v*v,20);return f'ভূমি থেকে {v} m/s বেগে সোজা ওপরে নিক্ষেপে অতিরিক্ত সর্বোচ্চ উচ্চতা কত? g = 10 m/s², বায়ুর বাধা নেই।',r,' m',f'½mv² = mgh; h = {v}²/(2×10) = {fmt(r)} m।',dict(v=v,g=g)
    if f=='brake-work':
        r=F(m*v*v,2);return f'{m} kg বস্তুকে {v} m/s থেকে থামানো হয়। শুধু বাধাদানকারী বলের লব্ধ কাজের পরমমান কত?',r,' J',f'Wনিট = 0−½mv²; পরমমান = ½×{m}×{v}² = {fmt(r)} J। আসল কাজ ঋণাত্মক।',dict(m=m,v=v)
    if f=='net-ke-change':
        u=2+n;v=u+4;r=F(m*(v*v-u*u),2);return f'{m} kg বস্তুর দ্রুতি {u} m/s থেকে {v} m/s হয়। লব্ধ কাজ কত?',r,' J',f'Wনিট = ½m(v²−u²) = ½×{m}×({v}²−{u}²) = {fmt(r)} J।',dict(m=m,u=u,v=v)
    if f=='friction-loss':
        fr=5+n;r=fr*s;return f'সমতল মেঝেতে পিছলানোর বিপরীতে {fr} N ধ্রুব ঘর্ষণ {s} m পথে কাজ করে। যান্ত্রিক শক্তির অপসৃত পরিমাণ কত? অন্য কোনো ক্ষয় নেই।',r,' J',f'ঘর্ষণের কাজ −fs; অপসৃত শক্তির মান = {fr}×{s} = {r} J।',dict(fr=fr,s=s)
    if f=='power-fv':
        r=force*v;return f'একই দিকে {force} N ধ্রুব টান ও {v} m/s ধ্রুব বেগে কাজের হার কত?',r,' W',f'P = Fv = {force}×{v} = {r} W। এটি ঐ টানের ক্ষমতা।',dict(force=force,v=v)
    raise ValueError(f)
FAMILIES=['horizontal-work','lift-work','distance','force','power','time','energy-pt','lift-power','lift-mass','kinetic','speed-ke','mass-ke','potential','height-pe','mass-pe','efficiency','useful-energy','input-energy','useful-power','input-power','kwh-joule','kw-watt','mechanical-total','fall-ke','fall-speed','rise-height','brake-work','net-ke-change','friction-loss','power-fv']
for f in FAMILIES:
    for n in range(10):
        q,r,unit,why,p=calc(f,n);r=F(r);wrong=[]
        for x in [r*2,r/2,r*F(3,2),r+1,r*10,r/10]:
            text=fmt(x)+unit
            if text!=fmt(r)+unit and text not in wrong:wrong.append(text)
            if len(wrong)==3:break
        mcq(q,fmt(r)+unit,wrong,why,f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit))

SHORTS='''পদার্থবিজ্ঞানের কাজ ও দৈনন্দিন পরিশ্রম এক নয়—ব্যাখ্যা করো।|যান্ত্রিক কাজে বলের প্রয়োগবিন্দুর সরণ এবং বলের সরণ-বরাবর উপাংশ দরকার। ভার ধরে স্থির দাঁড়ালেও শরীরে শক্তি ব্যয় হতে পারে, কিন্তু ভারে ধরে রাখার বলের যান্ত্রিক কাজ শূন্য।
ধ্রুব বলের ক্ষেত্রে কখন W = Fs সরাসরি ব্যবহার করা যায়?|বল ও সরণ একই সরলদিকে হলে। বিপরীত হলে কাজ −Fs, লম্ব হলে শূন্য; অন্য কোণে কেবল সরণ-বরাবর উপাংশ নিতে হয়।
ধনাত্মক ও ঋণাত্মক কাজের উদাহরণ দাও।|ওপরে তোলার সময় উত্তোলন বলের কাজ ধনাত্মক, ওজনের কাজ ঋণাত্মক। কারণ দুটি বলের দিক যথাক্রমে সরণের সঙ্গে একই ও বিপরীত।
বল থাকলেও কাজ শূন্য হতে পারে কীভাবে? দুটি পরিস্থিতি লেখো।|প্রয়োগবিন্দুর সরণ শূন্য হলে, যেমন না-সরা দেয়ালে ধাক্কা। আবার বল সরণের লম্ব হলেও শূন্য, যেমন সমতল অনুভূমিক চলায় ওজনের কাজ।
কাজ স্কেলার কেন, বল ভেক্টর হলেও?|কাজে বলের সরণ-বরাবর উপাংশকে সরণের মান দিয়ে গুণ করা হয়। ফলের ধনাত্মক/ঋণাত্মক মান থাকে, কিন্তু নিজস্ব স্থানিক দিক নেই।
কাজ ও শক্তির একক একই হওয়ার তাৎপর্য কী?|কাজের মাধ্যমে শক্তি স্থানান্তর হতে পারে। উভয়ের একক J ও মাত্রা ML²T⁻², তাই কোনো কাজে স্থানান্তরিত শক্তির পরিমাণ তুলনা করা যায়।
এক জুল কাজের সংজ্ঞা দাও।|1 N ধ্রুব বলের দিকে তার প্রয়োগবিন্দু 1 m সরলে ঐ বলের কাজ 1 J। অর্থাৎ 1 J = 1 N·m।
গতিশক্তি ও বিভবশক্তির পার্থক্য লেখো।|গতিশক্তি বস্তুর গতির জন্য; চলনে ½mv²। মহাকর্ষীয় বিভবশক্তি সিস্টেমের আপেক্ষিক অবস্থানের জন্য; পৃথিবীর কাছে শূন্যস্তর থেকে mgh।
একই ভরে দ্রুতি তিনগুণ হলে গতিশক্তি কত গুণ এবং কেন?|Eₖ = ½mv²। m স্থির রেখে v তিনগুণ হলে বর্গের জন্য গতিশক্তি নয়গুণ হয়।
একই গতিশক্তিতে বেশি ভরের বস্তু ধীরে চলে কেন?|v² = 2Eₖ/m। একই শক্তিতে ভর বেশি হলে দ্রুতির বর্গ কম, তাই দ্রুতি কম।
বিপরীতমুখী বেগে সমান ভর ও সমান দ্রুতি থাকলে গতিশক্তি সমান কেন?|গতিশক্তিতে দ্রুতির বর্গ থাকে; দিকের চিহ্ন থাকে না। তবে তাদের ভরবেগের দিক বিপরীত হতে পারে।
ভরবেগ ও গতিশক্তিকে একই রাশি বলা যায় না কেন?|p = mv ভেক্টর ও একক kg·m/s। Eₖ = ½mv² স্কেলার ও একক J; বেগের ওপর নির্ভরতাও আলাদা।
বিভবশক্তির শূন্যস্তর নির্বাচন করলেও শক্তির পরিবর্তন একই থাকে কেন?|দুটি অবস্থানের জন্য একই রেফারেন্স ব্যবহার করলে Eₚ২−Eₚ১ = mg(h₂−h₁)। শূন্যস্তর সরানোর একই ধ্রুবক দুই মান থেকে কাটে।
মহাকর্ষীয় বিভবশক্তি mgh সূত্রের সীমা কী?|পৃথিবীপৃষ্ঠের কাছাকাছি উচ্চতার পরিবর্তনে g প্রায় ধ্রুব ধরা হয়। বৃহৎ দূরত্বে g-এর পরিবর্তন উপেক্ষা করা না গেলে এই সরল রূপ সরাসরি যথাযথ নয়।
সমবেগে ভার ওপরে তুলতে কাজের ফল কোথায় সঞ্চিত হয়? ক্ষয় উপেক্ষা করো।|গতিশক্তি বদলায় না। উত্তোলন বলের কাজ পৃথিবী–বস্তু সিস্টেমের মহাকর্ষীয় বিভবশক্তি mgh বাড়ায়।
একই উচ্চতায় তুলতে সময় কম লাগলে কাজ ও ক্ষমতা কীভাবে বদলায়?|একই ভর ও g-তে উপযোগী কাজ mgh একই। সময় কম হলে P = W/t অনুযায়ী গড় উপযোগী ক্ষমতা বেশি হয়।
কাজ ও ক্ষমতার দুটি পার্থক্য লেখো।|কাজ শক্তি স্থানান্তরের পরিমাণ, একক J। ক্ষমতা সেই কাজের হার, একক W বা J/s; একই কাজ ভিন্ন সময়ে করলে ক্ষমতা ভিন্ন।
1 ওয়াট ক্ষমতার অর্থ কী?|প্রতি সেকেন্ডে 1 J হারে কাজ করা বা শক্তি স্থানান্তর করা। অর্থাৎ 1 W = 1 J/s।
গড় ক্ষমতা ও মুহূর্তের ক্ষমতা এক নাও হতে পারে কেন?|গড় ক্ষমতা মোট কাজ/মোট সময়। কাজের হার সময়ের সঙ্গে বদলালে নির্দিষ্ট মুহূর্তের হার এই গড়ের সমান নাও হয়।
P = Fv কখন ব্যবহার করবে?|একই দিকের বল ও প্রয়োগবিন্দুর বেগের জন্য P = Fv; বিপরীত হলে কাজের হার ঋণাত্মক। এখানে input বা net বা কোনো নির্দিষ্ট বলের ক্ষমতা—কোনটি তা স্পষ্ট করতে হবে।
যান্ত্রিক শক্তি সংরক্ষণে কী শর্ত দরকার?|বিবেচিত ব্যবস্থায় অনুপযোগী যান্ত্রিক ক্ষয় বা অন্য শক্তি সরবরাহ নেই এবং শুধু সংরক্ষণশীল প্রভাব বিবেচিত হলে গতিশক্তি ও বিভবশক্তির যোগ ধ্রুব থাকে। ঘর্ষণ থাকলে তা আলাদা হিসাবে নিতে হয়।
মুক্তপতনে গতিশক্তি বাড়লেও মোট শক্তি বাড়ে না কেন?|বায়ুর বাধা উপেক্ষায় হারানো মহাকর্ষীয় বিভবশক্তি সমান পরিমাণ গতিশক্তিতে যায়। যোগফল অপরিবর্তিত থাকে।
উল্লম্ব নিক্ষেপে সর্বোচ্চ বিন্দুতে কোন শক্তি সর্বাধিক ও কোনটি শূন্য?|আদর্শ ক্ষেত্রে মুহূর্তে বেগ শূন্য, তাই চলন গতিশক্তি শূন্য। একই রেফারেন্সে উচ্চতা সর্বাধিক বলে মহাকর্ষীয় বিভবশক্তি সর্বাধিক।
বায়ুর বাধা থাকলে পতনের যান্ত্রিক শক্তি কমে যায়—মোট শক্তি কি হারায়?|না। যান্ত্রিক শক্তির অংশ বায়ু ও বস্তুর তাপ, শব্দ ইত্যাদিতে ছড়িয়ে যায়। পরিবেশসহ মোট শক্তি হিসাবে নিলে সংরক্ষণ বজায় থাকে।
ব্রেক করলে গাড়ির গতিশক্তি কোথায় যায়?|প্রধানত ব্রেক, টায়ার ও রাস্তার তাপে এবং কিছু শব্দ/অন্যান্য রূপে। গাড়ি থামলেও শক্তি ধ্বংস হয় না, কেবল উপযোগী যান্ত্রিক রূপ কমে।
কাজ–গতিশক্তি উপপাদ্যে কেন লব্ধ কাজ নিতে হয়?|একাধিক বল শক্তি বাড়াতে বা কমাতে পারে। সব বলের কাজের বীজগাণিতিক যোগই মোট গতিশক্তি-পরিবর্তন; একা টানের কাজ সবসময় তার সমান নয়।
লব্ধ কাজ শূন্য হলেও আলাদা বলগুলো কাজ করতে পারে কি?|হ্যাঁ। সমতল পথে ঘর্ষণের বিপরীতে সমবেগে টানলে টানের ধনাত্মক ও ঘর্ষণের ঋণাত্মক কাজ সমান। যোগ শূন্য হওয়ায় গতিশক্তি অপরিবর্তিত।
ঘর্ষণের কাজ ঋণাত্মক মানেই শক্তি ঋণাত্মক হয়ে যায় কি?|না। এটি ঐ বলের দ্বারা বস্তুর যান্ত্রিক শক্তি কমার দিক বোঝায়। শেষ গতিশক্তি স্বাভাবিকভাবে অঋণাত্মক থাকে।
কর্মদক্ষতা বের করতে input ও useful output আলাদা করা জরুরি কেন?|সব আউটপুট উপযোগী নয়; তাপসহ অনুপযোগী অংশ থাকতে পারে। η = উপযোগী output/input; কোন কাজটি উপযোগী বলা হচ্ছে তা নির্দিষ্ট না করলে ফল অস্পষ্ট।
80% দক্ষতা মানে বাকি 20% শক্তি ধ্বংস নয় কেন?|ইনপুটের 80% নির্দিষ্ট কাজে লাগে, বাকি অংশ অন্য রূপে বা পরিবেশে যায়। শক্তি সংরক্ষণ নীতিতে মোট শক্তি ধ্বংস হয় না।
শক্তি ও ক্ষমতা দিয়ে দক্ষতা নির্ণয়ের সম্পর্ক লেখো।|একই সময়পর্বে η = Eউপযোগী/Eইন = Pউপযোগী,গড়/Pইন,গড়। শতকরা মান চাইলে 100 দিয়ে গুণ করতে হয়।
শুধু বেশি input ক্ষমতা মানেই বেশি উপযোগী output কি?|না। উপযোগী output = η × input। বেশি input-এর যন্ত্রের দক্ষতা কম হলে output অন্য যন্ত্রের চেয়ে কমও হতে পারে।
একই উপযোগী কাজ করতে দক্ষতা বাড়ালে জ্বালানি সাশ্রয় হয় কেন?|প্রয়োজনীয় input = useful output/η। output একই রেখে η বাড়ালে input ও একই শর্তে প্রয়োজনীয় জ্বালানি কমে।
কিলোওয়াট ও কিলোওয়াট-ঘণ্টার পার্থক্য লেখো।|kW ক্ষমতার একক। kWh ক্ষমতা ও সময়ের গুণফল, তাই শক্তির একক; 1 kWh = 3600000 J।
একই ক্ষমতার যন্ত্র দ্বিগুণ সময় চললে শক্তি ব্যয় কী হবে? শর্ত লেখো।|ধ্রুব input ক্ষমতা ধরে E = Pt। সময় দ্বিগুণ হলে শক্তি ব্যয়ও দ্বিগুণ; ক্ষমতা বা duty cycle বদলালে সরাসরি এ সিদ্ধান্ত নেওয়া যাবে না।
বিদ্যুতের বিলের উদাহরণে কাল্পনিক দর স্পষ্ট বলা দরকার কেন?|বিলের টাকা শক্তি ও প্রতি ইউনিট দরের ওপর নির্ভর করে। বাস্তব দর স্তর/সময়/অন্যান্য চার্জে বদলায়; অনুশীলনীর অনুমিত দরকে বর্তমান সরকারি হার বলা ঠিক নয়।
জলবিদ্যুতে শক্তি রূপান্তরের ধারাটি লেখো।|উঁচু জলের মহাকর্ষীয় বিভবশক্তি নিচে নামার গতিতে ও টারবাইনের যান্ত্রিক কাজে যায়। জেনারেটর তা বৈদ্যুতিক শক্তিতে রূপান্তর করে; কিছু অংশ ক্ষয় হয়।
বায়ুবিদ্যুৎ উৎপাদনে বায়ুর কোন বৈশিষ্ট্য কাজে লাগে?|প্রবাহিত বায়ুর গতিশক্তি টারবাইন ঘোরাতে কাজে লাগে। বাতাসের গতি ও প্রবাহ বদলালে উৎপাদনও বদলায়।
সৌর প্যানেল ও সৌর তাপসংগ্রাহকের উপযোগী output-এর পার্থক্য কী?|ফটোভোল্টাইক প্যানেল আলোক শক্তির অংশ সরাসরি বৈদ্যুতিক শক্তিতে দেয়। সৌর তাপসংগ্রাহক সূর্য থেকে তাপ সংগ্রহ করে পানি গরমের মতো কাজে লাগে।
সৌর শক্তি নবায়নযোগ্য হলেও সবসময় সমান output দেয় না কেন?|সূর্যালোক দিনরাত, মেঘ ও অবস্থানভেদে বদলায়। তাই স্থাপিত ক্ষমতা একই থাকলেও প্রতি মুহূর্তের output একই থাকে না।
নবায়নযোগ্য ও অনবায়নযোগ্য শক্তির উৎসের পার্থক্য উদাহরণসহ লেখো।|সৌর/বায়ু শক্তির প্রাকৃতিক প্রবাহ ব্যবহারকালীন সময়ে পুনরায় পাওয়া যায়। কয়লা/তেলের মজুত পুনর্গঠনে দীর্ঘ ভূতাত্ত্বিক সময় লাগে, তাই ব্যবহারসাপেক্ষে সীমিত।
জীবাশ্ম জ্বালানির ওপর অতিনির্ভরতার দুটি সমস্যা লেখো।|মজুত সীমিত এবং দহনে কার্বন ডাই-অক্সাইডসহ দূষণ সৃষ্টি হয়। সরবরাহের অনিশ্চয়তা ও পরিবেশগত ক্ষতি কমাতে সাশ্রয়/বিকল্প উৎস দরকার।
বায়োমাস ব্যবহার সব পরিস্থিতিতে পরিবেশবান্ধব বলা যায় না কেন?|কাঠ/জৈব উৎস পুনরুৎপাদনের চেয়ে দ্রুত ব্যবহার হলে ক্ষয় হয়। চাষ, পরিবহন ও দহনের দূষণসহ পুরো প্রক্রিয়া মূল্যায়ন করতে হয়।
নিউক্লীয় বিদ্যুৎকে জীবাশ্ম জ্বালানির দহন বলা যায় না কেন?|প্রধান শক্তি নিউক্লীয় বিক্রিয়া থেকে আসে, রাসায়নিক দহন থেকে নয়। পরে তাপ দিয়ে বিদ্যুৎ উৎপাদন হলেও শক্তির মূল উৎস ভিন্ন।
ব্যাটারিকে শক্তির সংরক্ষণব্যবস্থা বলার কারণ কী?|এতে রাসায়নিক রূপে শক্তি সঞ্চিত থাকে, যা প্রয়োজনে বৈদ্যুতিক শক্তিতে দেওয়া যায়। চার্জিং-ডিসচার্জিংয়ে ক্ষয় হয়; ব্যাটারি নতুন শক্তি সৃষ্টি করে না।
শক্তির অপচয় ও শক্তি ধ্বংসের পার্থক্য লেখো।|অপচয় মানে নির্দিষ্ট কাজে অনুপযোগী রূপে শক্তির ছড়িয়ে যাওয়া। ধ্বংস মানে শক্তির অস্তিত্ব হারানো, যা শক্তি সংরক্ষণ নীতির সঙ্গে মেলে না।
শক্তি সাশ্রয়ের দুটি বাস্তবসম্মত উপায় লেখো।|অপ্রয়োজনে যন্ত্র বন্ধ রাখা এবং একই উপযোগী কাজের জন্য বেশি দক্ষ যন্ত্র ব্যবহার করা। প্রয়োজনীয় নিরাপত্তা/সেবা বজায় রেখে অনাবশ্যক input কমানো উচিত।
একই উচ্চতায় ভিন্ন পথে ধীরে তোলা হলে আদর্শ উপযোগী কাজ কি বদলায়?|ঘর্ষণ ও গতিশক্তির পরিবর্তন উপেক্ষায় শুধু উচ্চতার পরিবর্তন গুরুত্বপূর্ণ: mgh। বাস্তবে দীর্ঘ পথে ঘর্ষণ থাকলে মোট input কাজ বাড়তে পারে।
একই ভরে গতিশক্তি চারগুণ হলে থামাতে কাজের পরমমান কী হয়?|থামার লব্ধ কাজ −Eₖ। তাই গতিশক্তি চারগুণে কাজের পরমমানও চারগুণ; একই ধ্রুব বাধাবলে পথও চারগুণ।
দক্ষতা বাড়ালেও মোট শক্তি সংরক্ষণ কীভাবে বজায় থাকে?|উপযোগী ভাগ বাড়ে ও অনুপযোগী ভাগ কমে। ইনপুটের সমান মোট উপযোগী ও অনুপযোগী শক্তি মিলে থাকে; কোনো অতিরিক্ত শক্তি সৃষ্টি হয় না।'''
for line in SHORTS.splitlines():
    q,s=line.split('|');add('SQ',q,s,'concept-short')
assert Counter(q['type'] for q in items)['SQ']==50
for f in ['horizontal-work','lift-power','kinetic','speed-ke','potential','efficiency','input-energy','kwh-joule','net-ke-change','power-fv']:
    for n in range(5):
        q,r,unit,why,p=calc(f,n)
        add('SQ',q.rstrip('।?')+'। সূত্র ও হিসাবের ধাপ দেখাও।',why,'short-'+f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit,baseFamily=f))

DEF_W=('কাজের SI একক কী?','জুল; 1 J = 1 N·m।')
DEF_K=('চলন গতিশক্তির সূত্র লেখো।','Eₖ = ½mv², যেখানে m ভর ও v দ্রুতি।')
DEF_P=('গড় ক্ষমতা কী?','মোট কাজ বা স্থানান্তরিত শক্তিকে মোট সময় দিয়ে ভাগ করলে গড় ক্ষমতা পাওয়া যায়।')
DEF_E=('কর্মদক্ষতার সংজ্ঞা দাও।','উপযোগী আউটপুট শক্তি ও মোট ইনপুট শক্তির অনুপাত; শতকরা হলে 100 দিয়ে গুণ।')
WHY_CON=('এখানে যান্ত্রিক শক্তি সংরক্ষণ কেন প্রযোজ্য?','শুধু মহাকর্ষীয় বিভবশক্তি ও গতিশক্তির বিনিময় হচ্ছে; বায়ুর বাধা/ঘর্ষণ বা অন্য সরবরাহ/ক্ষয় নেই বলা হয়েছে।')
WHY_EFF=('অনুপযোগী শক্তি কি ধ্বংস হয়?','না। তা তাপ/শব্দসহ অন্য রূপে বা পরিবেশে যায়; উপযোগী কাজে না লাগলেও মোট শক্তির হিসাবে থাকে।')
WHY_REF=('বিভবশক্তির শূন্যস্তর এক রাখা দরকার কেন?','পরম সংখ্যামান রেফারেন্সনির্ভর। সব অবস্থায় একই শূন্যস্তর রাখলে পরিবর্তন mgΔh সঙ্গত হয়।')
def cq(f,n,stem,definition,reason,gq,gs,hq,hs,params):
    pairs=[definition,reason,(gq,gs),(hq,hs)]
    parts=[dict(label=l,marks=m,question=q,solution=s) for l,m,(q,s) in zip('কখগঘ',[1,2,3,4],pairs)]
    add('CQ',stem,'বল, কাজের চিহ্ন, input/useful output ও শক্তির শূন্যস্তর আলাদা রাখো। সব হিসাব সামঞ্জস্যপূর্ণ এককে; প্রয়োজনমতো ছয় দশমিক পর্যন্ত আসন্ন মান।',f,dict(params={k:str(v) for k,v in params.items()},variant=n+1),parts=parts,difficulty='HARD')

for n in range(5):
    # 1: different works and net work.
    force=20+n*5;fr=5+n;s=4+n;net=(force-fr)*s
    cq('cq-pull-friction',n,f'সমতল পথে বাক্স ডানে {s} m সরে। ডানে ধ্রুব টান {force} N, বামে ধ্রুব ঘর্ষণ {fr} N। উল্লম্ব বলের কাজ শূন্য; অন্য কাজ নেই।',DEF_W,
       ('টান ও ঘর্ষণের কাজের চিহ্ন বিপরীত কেন?','টান সরণের দিকে, ঘর্ষণ সরণের বিপরীতে। তাই টানের কাজ ধনাত্মক ও ঘর্ষণের কাজ ঋণাত্মক।'),
       'দুই বলের কাজ ও লব্ধ কাজ নির্ণয় করো।',f'Wটান = {force*s} J; Wঘর্ষণ = −{fr*s} J। Wনিট = {net} J।',
       'গতিশক্তির পরিবর্তন কত? শুধু টানের কাজকে সেটি ধরলে কত ভুল হবে?',f'ΔEₖ = Wনিট = {net} J। টানের কাজ {force*s} J ধরলে {fr*s} J বেশি হয়; এই অংশ ঘর্ষণে অনুপযোগী রূপে যায়।',dict(force=force,fr=fr,s=s))
    # 2 lift work and power.
    m=10+n*5;h=4+n;t=5+n;g=10;work=m*g*h
    cq('cq-lift',n,f'এক উত্তোলক {m} kg ভার সমবেগে {h} m ওপরে তোলে {t} s-এ। g = 10 m/s²; ক্ষয় নেই এবং গতিশক্তি বদলায় না।',DEF_P,WHY_REF,
       'উত্তোলন বল ও মহাকর্ষের কাজ নির্ণয় করো।',f'উত্তোলন বলের কাজ = mgh = {work} J; মহাকর্ষের কাজ = −{work} J।',
       'উপযোগী ক্ষমতা ও লব্ধ কাজ বের করে একই মান কি না বোঝাও।',f'Pউপযোগী = {work}/{t} = {fmt(F(work,t))} W। লব্ধ কাজ = {work}−{work} = 0 J, তাই গতিশক্তি অপরিবর্তিত। উপযোগী কাজ বিভবশক্তি বাড়ায়; লব্ধ কাজের সঙ্গে এটি গুলানো যাবে না।',dict(m=m,h=h,t=t,g=g))
    # 3 same stairs/time comparison.
    m=40+n*5;h=3+n;t1=5+n;t2=10+n*2;g=10;work=m*g*h
    cq('cq-stairs-compare',n,f'{m} kg শিক্ষার্থী একই সিঁড়িতে {h} m উচ্চতায় দুইবার ওঠে। প্রথমবার {t1} s, দ্বিতীয়বার {t2} s লাগে। g = 10 m/s²। শুধু নিজের মহাকর্ষীয় বিভবশক্তি বৃদ্ধিকে উপযোগী কাজ ধরো।',DEF_P,
       ('একই উচ্চতায় সময় ভিন্ন হলেও উপযোগী কাজ একই কেন?','ভর ও g একই, উচ্চতার পরিবর্তনও একই। তাই বিভবশক্তি বৃদ্ধি mgh একই; শরীরের মোট বিপাকীয় ব্যয় এখানে হিসাব নয়।'),
       'দুইবারের উপযোগী গড় ক্ষমতা নির্ণয় করো।',f'W = mgh = {work} J। P₁ = {fmt(F(work,t1))} W, P₂ = {fmt(F(work,t2))} W।',
       'ক্ষমতার অনুপাত বের করে দ্রুত ওঠা মানেই বেশি উপযোগী কাজ কি না বিচার করো।',f'P₁/P₂ = t₂/t₁ = {fmt(F(t2,t1))}। উপযোগী কাজ উভয়ে {work} J; কম সময়ের কারণে ক্ষমতা বেশি, কাজ বেশি নয়।',dict(m=m,h=h,t1=t1,t2=t2,g=g))
    # 4 kinetic energy scaling.
    m=2+n;v=5+n;E=F(m*v*v,2)
    cq('cq-kinetic-scaling',n,f'{m} kg বস্তুর প্রথম দ্রুতি {v} m/s। পরে একই দিকে দ্রুতি দ্বিগুণ হয়; ভর অপরিবর্তিত। অন্য শক্তির পরিবর্তন নেই।',DEF_K,
       ('দ্রুতি দ্বিগুণে গতিশক্তি দ্বিগুণ নয় কেন?','গতিশক্তি ½mv²; এতে দ্রুতির বর্গ থাকে। তাই দ্বিগুণ দ্রুতিতে চারগুণ শক্তি লাগে।'),
       'প্রথম ও পরের গতিশক্তি নির্ণয় করো।',f'E₁ = ½×{m}×{v}² = {fmt(E)} J। E₂ = 4E₁ = {fmt(4*E)} J।',
       'এই পরিবর্তনে লব্ধ কাজ এবং পরে থামাতে কাজের মান নির্ণয় করো।',f'বাড়ানোর কাজ = E₂−E₁ = {fmt(3*E)} J। পরে থামাতে লব্ধ কাজ = −E₂ = {fmt(-4*E)} J। শক্তি-পরিবর্তন ও মোট শেষ শক্তি আলাদা।',dict(m=m,v=v))
    # 5 same kinetic energy different masses.
    m=2+n;v=8+n*2;E=F(m*v*v,2);M=4*m
    cq('cq-equal-ke',n,f'A-এর ভর {m} kg ও দ্রুতি {v} m/s। B-এর ভর {M} kg, কিন্তু চলন গতিশক্তি A-এর সমান।',DEF_K,
       ('একই গতিশক্তি মানে একই ভরবেগ নয় কেন?','Eₖ = p²/(2m); একই Eₖ-তে ভর আলাদা হলে ভরবেগের মান আলাদা হয়। বেগ ও ভরবেগের দিকও এই স্কেলার শক্তি দিয়ে নির্ধারিত নয়।'),
       'B-এর দ্রুতি নির্ণয় করো।',f'E = {fmt(E)} J। v_B² = 2E/{M} = {v*v//4}; v_B = {fmt(F(v,2))} m/s।',
       'দুজনের ভরবেগের মান তুলনা করো।',f'|p_A| = {m*v} kg·m/s। |p_B| = {M}×{fmt(F(v,2))} = {2*m*v} kg·m/s; B-এর মান দ্বিগুণ। একই শক্তিতে বেশি ভরের দ্রুতি কম হলেও ভরবেগের মান বেশি।',dict(m=m,v=v,M=M))
    # 6 height change and reference.
    m=3+n;h1=2+n;h2=8+n*2;g=10;U1=m*g*h1;U2=m*g*h2
    cq('cq-potential-reference',n,f'{m} kg বস্তু ভূমি থেকে {h1} m উচ্চতা থেকে {h2} m উচ্চতায় যায়। g = 10 m/s²। প্রথমে ভূমিকে শূন্যস্তর ধরো।',DEF_W,WHY_REF,
       'দুই অবস্থার বিভবশক্তি ও তার পরিবর্তন নির্ণয় করো।',f'U₁ = {U1} J; U₂ = {U2} J; ΔU = {U2-U1} J।',
       'প্রথম অবস্থানকে শূন্যস্তর ধরলে শেষ বিভবশক্তি ও মহাকর্ষের কাজ কত?',f'নতুন শূন্যস্তরে শেষ U = mg(h₂−h₁) = {U2-U1} J। মহাকর্ষের কাজ = −ΔU = {U1-U2} J। রেফারেন্স বদলালেও দুই অবস্থার পরিবর্তন একই।',dict(m=m,h1=h1,h2=h2,g=g))
    # 7 drop from rest with exact-square height.
    m=2+n;v=10+n*2;g=10;H=F(v*v,2*g);E=m*g*H
    cq('cq-freefall',n,f'{m} kg বস্তু {fmt(H)} m উচ্চতা থেকে স্থির অবস্থায় ছাড়া হয়। g = 10 m/s²; ভূমিকে শূন্য বিভবস্তর ধরো। বায়ুর বাধা নেই; আঘাতের আগের গতি বিবেচনা করো।',DEF_K,WHY_CON,
       'মাটিতে লাগার ঠিক আগের গতিশক্তি ও দ্রুতি নির্ণয় করো।',f'Eₖ = mgH = {fmt(E)} J। v² = 2gH = {v*v}; v = {v} m/s।',
       'অর্ধেক উচ্চতায় বিভবশক্তি ও গতিশক্তি নির্ণয় করো।',f'U = mgH/2 = {fmt(E/2)} J; K = E−U = {fmt(E/2)} J। তখনও মোট শক্তি {fmt(E)} J; অর্ধেক উচ্চতা মানে অর্ধেক দ্রুতি নয়।',dict(m=m,H=H,g=g))
    # 8 upward throw.
    m=2+n;u=10+n*4;g=10;E=F(m*u*u,2);H=F(u*u,2*g)
    cq('cq-upward-energy',n,f'ভূমি থেকে {m} kg বল সোজা ওপরে {u} m/s বেগে ছোড়া হয়। g = 10 m/s²; ভূমি শূন্যস্তর, বায়ুর বাধা নেই।',DEF_K,WHY_CON,
       'সর্বোচ্চ উচ্চতা নির্ণয় করো।',f'আদি K = {fmt(E)} J; চূড়ায় সব বিভবশক্তি। H = u²/(2g) = {fmt(H)} m।',
       'চূড়ায় ও ভূমিতে ফেরার ঠিক আগে শক্তি ও দ্রুতি তুলনা করো।',f'চূড়ায় K = 0 J, U = {fmt(E)} J। ফেরার আগে U = 0 J, K = {fmt(E)} J ও দ্রুতি {u} m/s। বেগের দিক ফেরার সময় নিচে; শক্তি দিক বলে না।',dict(m=m,u=u,g=g))
    # 9 initial downward speed at a height; exact final speed.
    m=3+n;u=6+n*2;v=u+4;g=10;H=F(v*v-u*u,2*g);E=F(m*v*v,2)
    cq('cq-falling-initial-speed',n,f'{m} kg বল ভূমি থেকে {fmt(H)} m উচ্চতায় নিচের দিকে {u} m/s আদিবেগে আছে। g = 10 m/s², বায়ুর বাধা নেই; ভূমি শূন্যস্তর।',DEF_K,WHY_CON,
       'শুরুতে মোট যান্ত্রিক শক্তি নির্ণয় করো।',f'E = ½mu²+mgH = {fmt(F(m*u*u,2))}+{fmt(m*g*H)} = {fmt(E)} J।',
       'ভূমিতে লাগার আগের দ্রুতি নির্ণয় করো; স্থির থেকে পড়ার সূত্র সরাসরি ভুল কেন?',f'½mv² = E; v² = {v*v}; v = {v} m/s। এখানে আদিতেই {fmt(F(m*u*u,2))} J গতিশক্তি ছিল; সেটি বাদ দিয়ে শুধু mgH নিলে দ্রুতি কম আসবে।',dict(m=m,u=u,H=H,g=g))
    # 10 known total and height speed.
    m=2+n;v=6+n*2;h=3+n;g=10;E=F(m*v*v,2)+m*g*h
    cq('cq-known-mechanical',n,f'{m} kg বস্তুর মোট যান্ত্রিক শক্তি {fmt(E)} J। এটি ভূমির {h} m ওপরে আছে। g = 10 m/s², ভূমি শূন্যস্তর; এরপর শুধু মহাকর্ষের প্রভাব।',DEF_K,WHY_REF,
       'ঐ উচ্চতায় গতিশক্তি ও দ্রুতি নির্ণয় করো।',f'U = mgh = {m*g*h} J। K = E−U = {fmt(F(m*v*v,2))} J; v = √(2K/m) = {v} m/s।',
       'সর্বোচ্চ সম্ভব উচ্চতা নির্ণয় করে কেন এর ওপরে যাওয়া যাবে না বোঝাও।',f'Hmax = E/(mg) = {fmt(E/(m*g))} m। এর ওপরে U > E হলে K ঋণাত্মক লাগবে, যা সম্ভব নয়। এটি শক্তির অনুমোদিত সর্বোচ্চ সীমা; সেখানে পৌঁছানোর পথ/দিক আলাদা গতির শর্তের বিষয়।',dict(m=m,E=E,h=h,g=g))
    # 11 net work to speed.
    m=2+n;u=4+n*2;v=u+4;s=2+n;work=F(m*(v*v-u*u),2);force=work/s
    cq('cq-work-speed',n,f'সমতল পথে {m} kg বস্তুর আদিদ্রুতি {u} m/s। সরণের দিকে {fmt(force)} N ধ্রুব লব্ধ বল {s} m কাজ করে। অন্য শক্তির পরিবর্তন নেই।',DEF_W,
       ('এখানে প্রয়োগ করা বল নয়, লব্ধ বল বলা গুরুত্বপূর্ণ কেন?','সব বলের কাজের যোগই গতিশক্তির পরিবর্তন। একা কোনো টানের কাজ নিলে ঘর্ষণের মতো অন্য কাজ বাদ পড়তে পারে।'),
       'লব্ধ কাজ নির্ণয় করো।',f'Wনিট = Fs = {fmt(force)}×{s} = {fmt(work)} J।',
       'শেষদ্রুতি নির্ণয় করে বল দ্বিগুণ মানেই দ্রুতি দ্বিগুণ নয় কেন বোঝাও।',f'½mv² = ½mu²+Wনিট; v² = {v*v}, v = {v} m/s। দ্বিগুণ বল একই পথে দ্বিগুণ কাজ দেয়; কিন্তু আদি শক্তিসহ গতিশক্তি ও দ্রুতির বর্গের সম্পর্ক থাকায় দ্রুতি সাধারণভাবে দ্বিগুণ হয় না।',dict(m=m,u=u,force=force,s=s))
    # 12 stopping energy.
    m=4+n;u=10+n*2;force=20+n*10;K=F(m*u*u,2);distance=K/force
    cq('cq-stop-work',n,f'{m} kg ট্রলি {u} m/s আদিদ্রুতি থেকে থামে। আদিবেগের বিপরীতে {force} N ধ্রুব লব্ধ বাধাদানকারী বল থামা পর্যন্ত থাকে। পথ অনুভূমিক।',DEF_K,
       ('থামার লব্ধ কাজ ঋণাত্মক কেন?','শেষ গতিশক্তি শূন্য; তাই ΔK = 0−Kপ্রথম। বাধাদানকারী বল সরণের বিপরীতে কাজ করে।'),
       'থামাতে লব্ধ কাজ ও থামার দূরত্ব নির্ণয় করো।',f'Wনিট = −½mu² = {fmt(-K)} J। −Fs = −K থেকে s = {fmt(distance)} m।',
       'একই বলের মানে আদিদ্রুতি দ্বিগুণ করলে কাজ ও দূরত্ব কত হবে?',f'নতুন K = 4K = {fmt(4*K)} J; কাজ = {fmt(-4*K)} J, দূরত্ব = {fmt(4*distance)} m। শক্তি দ্রুতির বর্গের সঙ্গে বাড়ে।',dict(m=m,u=u,force=force))
    # 13 two intervals of work.
    F1=10+n*2;s1=3+n;F2=6+n;s2=4+n;W1=F1*s1;W2=F2*s2
    cq('cq-two-stage-work',n,f'এক বস্তু সোজা ডানে চলে। প্রথম {s1} m-এ লব্ধ বল ডানে {F1} N, পরের {s2} m-এ লব্ধ বলও ডানে {F2} N। প্রতিটি পর্বে বল ধ্রুব।',DEF_W,
       ('দুই পর্বে একটি বল ধরে কাজ করা যায় না কেন?','বল দুটি ভিন্ন পথাংশে আলাদা মানে ক্রিয়া করে। প্রতিটি পর্বের কাজ বের করে যোগ করতে হয়।'),
       'মোট লব্ধ কাজ নির্ণয় করো।',f'W₁ = {W1} J, W₂ = {W2} J; মোট W = {W1+W2} J।',
       'পুরো পথে একই মোট কাজ দিত এমন ধ্রুব লব্ধ বল কত? সরল গড় কি সবসময় ঠিক?',f'সমতুল্য F = ({W1}+{W2})/({s1}+{s2}) = {fmt(F(W1+W2,s1+s2))} N। পথ-ওজনযুক্ত গড় দরকার; পথদুটি সমান না হলে শুধু (F₁+F₂)/2 সাধারণভাবে যথাযথ নয়।',dict(F1=F1,s1=s1,F2=F2,s2=s2))
    # 14 motor lifting with efficiency.
    m=20+n*10;h=4+n;t=8+n*2;g=10;eta=F(3,4);W=m*g*h;out=F(W,t);inp=out/eta
    cq('cq-motor-lift',n,f'মোটর {m} kg ভার {h} m ওপরে সমবেগে তুলতে {t} s নেয়। g = 10 m/s², কর্মদক্ষতা 75%। উপযোগী output শুধু বিভবশক্তি বৃদ্ধি।',DEF_E,WHY_EFF,
       'উপযোগী গড় ক্ষমতা নির্ণয় করো।',f'Pউপযোগী = mgh/t = {W}/{t} = {fmt(out)} W।',
       'ইনপুট ক্ষমতা ও ঐ সময়ে অনুপযোগী শক্তি নির্ণয় করো।',f'Pইন = Pউপযোগী/0.75 = {fmt(inp)} W। Eক্ষয় = Pইনt−mgh = {fmt(inp*t-W)} J। এটি শক্তি ধ্বংস নয়।',dict(m=m,h=h,t=t,g=g,percent=75))
    # 15 pumping a finite water volume.
    volume=F(2+n,10);rho=1000;h=5+n;t=20+n*5;g=10;m=rho*volume;W=m*g*h
    cq('cq-water-pump',n,f'পাম্প {fmt(volume)} m³ জল একই প্রাথমিক স্তর থেকে {h} m উঁচু ট্যাংকে তোলে {t} s-এ। ρ = 1000 kg/m³, g = 10 m/s²। সব জলের জন্য উচ্চতার পরিবর্তন একই; ক্ষয় ও বেগের পরিবর্তন উপেক্ষা করো।',DEF_P,
       ('উপযোগী কাজের জন্য আয়তনকে ভরে রূপান্তর প্রয়োজন কেন?','মহাকর্ষীয় বিভবশক্তি বৃদ্ধি mgh-তে ভর লাগে। আয়তন V ও ঘনত্ব ρ থেকে m = ρV পাওয়া যায়।'),
       'জলের ভর ও উপযোগী কাজ নির্ণয় করো।',f'm = ρV = {fmt(m)} kg। W = mgh = {fmt(W)} J।',
       'পাম্পের গড় উপযোগী ক্ষমতা এবং অর্ধেক সময়ে একই কাজের ক্ষমতা নির্ণয় করো।',f'P = W/t = {fmt(W/t)} W। অর্ধেক সময়ে Pনতুন = {fmt(2*W/t)} W; ভর ও উচ্চতা একই বলে কাজ একই থাকে।',dict(volume=volume,rho=rho,h=h,t=t,g=g))
    # 16 energy efficiency.
    inp=2000+n*500;out=F(inp*3,5);loss=inp-out
    cq('cq-efficiency-energy',n,f'এক যন্ত্র {inp} J শক্তি গ্রহণ করে নির্দিষ্ট কাজে {fmt(out)} J উপযোগী শক্তি দেয়। অবশিষ্ট শক্তি তাপসহ অনুপযোগী রূপে যায়।',DEF_E,WHY_EFF,
       'শতকরা কর্মদক্ষতা ও অনুপযোগী শক্তি নির্ণয় করো।',f'η = {fmt(out)}/{inp}×100 = 60%। Eঅনুপযোগী = {fmt(loss)} J।',
       'দক্ষতা 75% হলে একই উপযোগী কাজের ইনপুট ও সাশ্রয় কত হতো?',f'Eইন,নতুন = {fmt(out)}/0.75 = {fmt(out/F(3,4))} J। সাশ্রয় = {inp}−Eইন,নতুন = {fmt(F(inp)-out/F(3,4))} J। উপযোগী কাজ অপরিবর্তিত; কম ক্ষয় হলে কম ইনপুট লাগে।',dict(inp=inp,out=out,newpercent=75))
    # 17 powers efficiency and time.
    inp=500+n*100;out=F(inp*4,5);t=10+n*5
    cq('cq-efficiency-power',n,f'এক যন্ত্রের ধ্রুব ইনপুট ক্ষমতা {inp} W ও উপযোগী আউটপুট {fmt(out)} W। এটি {t} s চলে।',DEF_E,WHY_EFF,
       'দক্ষতা ও অনুপযোগী ক্ষমতা নির্ণয় করো।',f'η = {fmt(out)}/{inp}×100 = 80%। Pক্ষয় = {fmt(inp-out)} W।',
       'এই সময়ে উপযোগী ও অনুপযোগী শক্তি নির্ণয় করে মোট ইনপুটের সঙ্গে মিলাও।',f'Eউপযোগী = {fmt(out*t)} J; Eক্ষয় = {fmt((inp-out)*t)} J। যোগ = {inp*t} J = Pইনt; মোট শক্তি মিলে যায়।',dict(inp=inp,out=out,t=t))
    # 18 fuel energy per mass specified.
    fuel=F(2+n,10);q=40000000;eta=F(1,4);useful=fuel*q*eta
    cq('cq-fuel-energy',n,f'এক ইঞ্জিন {fmt(fuel)} kg জ্বালানি ব্যবহার করে। প্রতি kg জ্বালানি থেকে 40000000 J শক্তি পাওয়া যায়। নির্দিষ্ট কাজের দক্ষতা 25%।',DEF_E,WHY_EFF,
       'ইনপুট ও উপযোগী শক্তি নির্ণয় করো।',f'Eইন = {fmt(fuel)}×40000000 = {fmt(fuel*q)} J। Eউপযোগী = 0.25Eইন = {fmt(useful)} J।',
       'একই কাজ 40% দক্ষতায় করতে জ্বালানি কত লাগবে? সাশ্রয় কত?',f'mনতুন = Eউপযোগী/(0.40×40000000) = {fmt(useful/(F(2,5)*q))} kg। সাশ্রয় = {fmt(fuel-useful/(F(2,5)*q))} kg। একই প্রতি-kg শক্তি ধরে তুলনা; বাস্তব জ্বালানির পরিবর্তন এখানে নেই।',dict(fuel=fuel,q=q,percent=25,newpercent=40))
    # 19 kWh and hypothetical tariff.
    power=500+n*100;hours=2+n;rate=8;energy=F(power*hours,1000)
    cq('cq-kwh-cost',n,f'{power} W ধ্রুব ইনপুটের যন্ত্র প্রতিদিন {hours} h চলে। অনুশীলনীর কাল্পনিক দর প্রতি kWh 8 টাকা; অন্য চার্জ নেই। এটি বর্তমান সরকারি ট্যারিফ নয়।',DEF_P,
       ('kW ও kWh এক রাশি নয় কেন?','kW ক্ষমতা, kWh ক্ষমতা × সময় বা শক্তি। বিলের জন্য ব্যবহৃত শক্তি লাগে, শুধু ক্ষমতা নয়।'),
       'এক দিনের ব্যবহৃত শক্তি kWh ও J-এ নির্ণয় করো।',f'E = ({power}/1000)×{hours} = {fmt(energy)} kWh = {fmt(energy*3600000)} J।',
       '30 দিনে বিল ও প্রতিদিন সময় অর্ধেক করলে সাশ্রয় নির্ণয় করো।',f'বিল = {fmt(energy)}×30×8 = {fmt(energy*30*rate)} টাকা। অর্ধেক সময়ে একই ধ্রুব ক্ষমতায় বিলও অর্ধেক; সাশ্রয় {fmt(energy*15*rate)} টাকা। বাস্তব বিলের অন্য চার্জ এখানে নেই।',dict(power=power,hours=hours,rate=rate,days=30))
    # 20 time from input and efficiency.
    inp=400+n*100;eta=F(3,5);work=1200+n*600;out=inp*eta;t=F(work)/out
    cq('cq-output-time',n,f'এক যন্ত্রের ধ্রুব ইনপুট ক্ষমতা {inp} W ও দক্ষতা 60%। এটি {work} J উপযোগী কাজ করবে।',DEF_P,WHY_EFF,
       'উপযোগী ক্ষমতা ও প্রয়োজনীয় সময় নির্ণয় করো।',f'Pউপযোগী = 0.60×{inp} = {fmt(out)} W। t = W/Pউপযোগী = {work}/{fmt(out)} = {fmt(t)} s।',
       'ওই কাজে ইনপুট শক্তি ও অনুপযোগী শক্তি নির্ণয় করো।',f'Eইন = {work}/0.60 = {fmt(F(work)/eta)} J। Eক্ষয় = Eইন−{work} = {fmt(F(work)/eta-work)} J। সময় বের করতে ইনপুট ক্ষমতাকে উপযোগী ক্ষমতা ধরলে কম সময় পাওয়া যেত।',dict(inp=inp,percent=60,work=work))
    # 21 compare machines same input.
    inp=500+n*100;eta1=F(1,2);eta2=F(4,5);work=2000+n*1000;P1=inp*eta1;P2=inp*eta2
    cq('cq-compare-machines',n,f'A ও B যন্ত্রের ইনপুট ক্ষমতা উভয়ের {inp} W। দক্ষতা যথাক্রমে 50% ও 80%। প্রত্যেককে একই {work} J উপযোগী কাজ করতে হবে; হারগুলো ধ্রুব।',DEF_E,WHY_EFF,
       'দুটি যন্ত্রের উপযোগী ক্ষমতা নির্ণয় করো।',f'P_A = {fmt(P1)} W; P_B = {fmt(P2)} W।',
       'কাজ শেষের সময় ও ইনপুট শক্তি তুলনা করো।',f't_A = {fmt(F(work)/P1)} s, t_B = {fmt(F(work)/P2)} s। Eইন,A = {fmt(F(work)/eta1)} J, Eইন,B = {fmt(F(work)/eta2)} J। B কম সময় ও কম ইনপুট নেয়; একই input rating মানেই একই useful output নয়।',dict(inp=inp,percent1=50,percent2=80,work=work))
    # 22 constant speed force power.
    force=100+n*20;speed=3+n;t=10+n;P=force*speed;work=P*t
    cq('cq-force-speed-power',n,f'এক গাড়ি সোজা পথে {speed} m/s ধ্রুব বেগে চলে। সামনে ইঞ্জিনের টান {force} N, পেছনের মোট প্রতিরোধও সমান। এই অবস্থা {t} s থাকে।',DEF_P,
       ('সমবেগে ইঞ্জিনের কাজ শূন্য নয় কেন?','সমবেগে শুধু লব্ধ কাজ শূন্য। ইঞ্জিন ধনাত্মক কাজ করে এবং প্রতিরোধ সমান ঋণাত্মক কাজ করে।'),
       'ইঞ্জিনের যান্ত্রিক ক্ষমতা ও কাজ নির্ণয় করো।',f'P = Fv = {P} W। W = Pt = {work} J।',
       'লব্ধ কাজ ও গতিশক্তির পরিবর্তন নির্ণয় করে শক্তি কোথায় যায় বোঝাও।',f'প্রতিরোধের কাজ = −{work} J; লব্ধ কাজ = 0 J = ΔK। ইঞ্জিনের দেওয়া শক্তি প্রতিরোধে অনুপযোগী রূপে যায়; সমবেগ মানে শক্তি সরবরাহহীন চলা নয়।',dict(force=force,speed=speed,t=t))
    # 23 kinetic energy from momentum.
    m=2+n;v=6+n*2;p=m*v;E=F(p*p,2*m)
    cq('cq-momentum-energy',n,f'এক বস্তুর ভর {m} kg ও ভরবেগের মান {p} kg·m/s। নিউটনীয় চলন বিবেচনা করো; ঘূর্ণন নেই।',DEF_K,
       ('গতিশক্তি ভরবেগের দিক নির্ধারণ করে না কেন?','Eₖ = p²/(2m)-এ ভরবেগের মানের বর্গ থাকে। একই মানের বিপরীত ভরবেগেও একই গতিশক্তি হয়।'),
       'বস্তুর দ্রুতি ও গতিশক্তি নির্ণয় করো।',f'v = p/m = {v} m/s। Eₖ = p²/(2m) = {fmt(E)} J।',
       'ভরবেগের মান দ্বিগুণ কিন্তু ভর একই হলে শক্তি ও থামানোর কাজ কী হবে?',f'নতুন Eₖ = 4Eₖ = {fmt(4*E)} J। থামাতে লব্ধ কাজ = {fmt(-4*E)} J। ভরবেগ দ্বিগুণে কাজের পরমমান দ্বিগুণ নয়, চারগুণ।',dict(m=m,p=p))
    # 24 descent with explicitly given dissipated energy.
    m=4+n;g=10;H=8+n*2;h=2+n;available=m*g*(H-h);loss=F(available,4);K=available-loss
    cq('cq-descent-loss',n,f'{m} kg বস্তু স্থির থেকে ভূমির {H} m উচ্চতা থেকে {h} m উচ্চতায় নামে। g = 10 m/s²; এই পথে ঘর্ষণে {fmt(loss)} J যান্ত্রিক শক্তি অন্য রূপে যায়। আর কোনো সরবরাহ/ক্ষয় নেই; ভূমি শূন্যস্তর।',DEF_K,WHY_REF,
       'বিভবশক্তির হ্রাস ও শেষে গতিশক্তি নির্ণয় করো।',f'হারানো U = mg(H−h) = {available} J। Kশেষ = {available}−{fmt(loss)} = {fmt(K)} J।',
       'প্রথম ও শেষ মোট যান্ত্রিক শক্তি তুলনা করে মোট শক্তি সংরক্ষণ ব্যাখ্যা করো।',f'Eপ্রথম = {m*g*H} J; Eশেষ = Kশেষ+mgh = {fmt(K+m*g*h)} J। পার্থক্য {fmt(loss)} J, যা তাপসহ অন্য রূপে গেছে। যান্ত্রিক শক্তি কমলেও পরিবেশসহ মোট শক্তি হারায়নি।',dict(m=m,g=g,H=H,h=h,loss=loss))
    # 25 loss fraction at a collision.
    m=2+n;u=10+n*2;v=F(u,2);before=F(m*u*u,2);after=F(m)*v*v/2
    cq('cq-speed-loss',n,f'{m} kg বস্তু একই অনুভূমিক স্তরে বাধার সঙ্গে আন্তঃক্রিয়ার আগে {u} m/s ও পরে {fmt(v)} m/s দ্রুতিতে চলে। ভর অপরিবর্তিত; বস্তুর অন্য কোনো সঞ্চিত শক্তি পরিবর্তন নেই।',DEF_K,
       ('বেগের মান কমার ফলে শক্তি-হ্রাসের অংশ শুধু বেগের অনুপাত নয় কেন?','চলন গতিশক্তি দ্রুতির বর্গের সমানুপাতিক। তাই অর্ধেক দ্রুতি হলে শক্তি এক-চতুর্থাংশ থাকে।'),
       'আগের ও পরের গতিশক্তি নির্ণয় করো।',f'Kআগে = {fmt(before)} J, Kপরে = {fmt(after)} J।',
       'বস্তু থেকে অন্যত্র স্থানান্তরিত শক্তি ও আগের শক্তির শতকরা ভাগ নির্ণয় করো।',f'স্থানান্তরিত = {fmt(before-after)} J। শতকরা = (Kআগে−Kপরে)/Kআগে×100 = 75%। এই শক্তি বাধা/পরিবেশে যেতে পারে; ধ্বংস নয়।',dict(m=m,u=u,v=v))
    # 26 unit conversion for kinetic energy.
    m=100+n*50;kmh=36+n*18;speed=F(kmh)*5/18;E=F(m)*speed*speed/2
    cq('cq-ke-units',n,f'{m} kg গাড়ির দ্রুতি {kmh} km/h। চলন গতিশক্তি নির্ণয়ে SI একক নিতে হবে; ঘূর্ণন বাদ।',DEF_K,
       ('km/h-এর সংখ্যা সরাসরি SI গতিশক্তির সূত্রে বসানো ভুল কেন?','m kg-এ হলে v-কে m/s-এ নিতে হয়। km/h = (5/18) m/s; বেগের রূপান্তর বর্গ আকারে শক্তিতে প্রভাব ফেলে।'),
       'দ্রুতি m/s-এ ও গতিশক্তি নির্ণয় করো।',f'v = {kmh}×5/18 = {fmt(speed)} m/s। K = ½mv² = {fmt(E)} J।',
       'বেগের একক না বদলে শুধু সংখ্যাটি বসালে কত গুণ ভুল শক্তি হতো?',f'ভুল/সঠিক = (18/5)² = {fmt(F(18,5)**2)}। ভুল শক্তি = {fmt(F(m*kmh*kmh,2))} J লেখা হতো; সংখ্যামান বেশি হতো। সঠিক একক ছাড়া মাত্রা-সদৃশ লিখলেই হিসাব ঠিক হয় না।',dict(m=m,kmh=kmh))
    # 27 repeated identical lifts, include rest time.
    m=10+n*5;h=3+n;trips=4+n;moving=5+n;rest=2;g=10;work=m*g*h*trips;total=trips*(moving+rest)
    cq('cq-repeated-lifts',n,f'এক যন্ত্র প্রতিবার {m} kg নতুন ভার {h} m ওপরে সমবেগে তোলে। এমন {trips} বার কাজ; প্রতিবার তুলতে {moving} s এবং প্রতিবারের পর, শেষবারসহ, {rest} s বিরতি। g = 10 m/s²। শুধু ভারগুলোর বিভবশক্তি বৃদ্ধি উপযোগী কাজ।',DEF_P,
       ('পুরো প্রক্রিয়ার গড় উপযোগী ক্ষমতায় বিরতি ধরতে হবে কেন?','বিরতিতে উপযোগী কাজ হয় না কিন্তু মোট অতিবাহিত সময় বাড়ে। পুরো প্রক্রিয়ার গড় চাইলে সেটিও হরে নিতে হয়।'),
       'মোট উপযোগী কাজ ও মোট সময় নির্ণয় করো।',f'W = {trips}mgh = {work} J। tমোট = {trips}({moving}+{rest}) = {total} s।',
       'বিরতিসহ ও শুধু উত্তোলনের সময়ের গড় ক্ষমতা তুলনা করো।',f'পুরো গড় = {fmt(F(work,total))} W। শুধু উত্তোলনের সময় = {trips*moving} s; ঐ সময়ের গড় = {fmt(F(work,trips*moving))} W। দ্বিতীয়টি বেশি; কোন সময়পর্বের গড় তা স্পষ্ট রাখতে হয়।',dict(m=m,h=h,trips=trips,moving=moving,rest=rest,g=g))
    # 28 percentage power lost.
    inp=800+n*200;losspercent=20+n*5;loss=F(inp*losspercent,100);out=inp-loss;t=10+n
    cq('cq-power-loss-percent',n,f'এক যন্ত্রের ধ্রুব ইনপুট ক্ষমতা {inp} W। ইনপুটের {losspercent}% নির্দিষ্ট কাজে অনুপযোগী। এটি {t} s চলে; বাকি অংশই useful output।',DEF_E,WHY_EFF,
       'উপযোগী ক্ষমতা ও দক্ষতা নির্ণয় করো।',f'Pঅনুপযোগী = {fmt(loss)} W। Pউপযোগী = {fmt(out)} W; দক্ষতা = {100-losspercent}%।',
       'এই সময়ে উপযোগী ও মোট ইনপুট শক্তি নির্ণয় করে অনুপাত দেখাও।',f'Eউপযোগী = {fmt(out*t)} J; Eইন = {inp*t} J। অনুপাত = {fmt(out/F(inp))}; শক্তি ও ক্ষমতা দিয়ে একই সময়ের দক্ষতা একই আসে।',dict(inp=inp,losspercent=losspercent,t=t))
    # 29 solar panel with explicit incident density.
    intensity=500+n*100;area=2+n;t=10+n*5;eta=F(1,5);pin=intensity*area;pout=pin*eta
    cq('cq-solar-conversion',n,f'এক সৌর প্যানেলে প্রতি m²-এ {intensity} W হারে আলোক শক্তি লম্বভাবে পড়ে। গ্রহণকারী ক্ষেত্রফল {area} m², বৈদ্যুতিক দক্ষতা 20%; এই অবস্থা {t} s ধ্রুব থাকে। ছায়া নেই।',DEF_E,
       ('সৌর output ধ্রুব থাকবে বলা হয়েছে কেন?', 'হিসাবে E = Pt নিতে আলো, কার্যকর ক্ষেত্রফল ও দক্ষতা এই সময়ে অপরিবর্তিত ধরা হয়েছে। বাস্তবে মেঘ বা দিক বদলালে output বদলাতে পারে।'),
       'আপতিত ক্ষমতা ও বৈদ্যুতিক output ক্ষমতা নির্ণয় করো।',f'Pইন = {intensity}×{area} = {pin} W। Pইলেকট্রিক = 0.20Pইন = {fmt(pout)} W।',
       'বৈদ্যুতিক শক্তি ও অনুপযোগী অংশ নির্ণয় করে নবায়নযোগ্য মানেই ক্ষয়হীন কি না বোঝাও।',f'Eইলেকট্রিক = {fmt(pout*t)} J; অন্য অংশ = (Pইন−Pইলেকট্রিক)t = {fmt((pin-pout)*t)} J। উৎস নবায়নযোগ্য হলেও যন্ত্রের conversion দক্ষতা 100% নয়।',dict(intensity=intensity,area=area,t=t,percent=20))
    # 30 hydro with steady flow.
    flow=F(1+n,10);rho=1000;H=5+n;g=10;eta=F(4,5);pin=rho*flow*g*H;pout=pin*eta;t=20+n*5
    cq('cq-hydro-flow',n,f'জলবিদ্যুৎ ব্যবস্থায় প্রতি সেকেন্ডে {fmt(flow)} m³ জল {H} m উচ্চতা হারায়। ρ = 1000 kg/m³, g = 10 m/s², সামগ্রিক বৈদ্যুতিক দক্ষতা 80%। প্রবাহ {t} s ধ্রুব; আগের-পরে গতিশক্তির পার্থক্য উপেক্ষা করো।',DEF_P,
       ('প্রতি সেকেন্ডের জলের বিভবশক্তি-হ্রাস ক্ষমতা কেন?', 'প্রতি সেকেন্ডে যত ভর নামে তার হার ρQ। সেই ভরহারের জন্য ρQgH হলো প্রতি সেকেন্ডে শক্তি, একক W।'),
       'জল থেকে পাওয়া যান্ত্রিক শক্তির হার ও বৈদ্যুতিক ক্ষমতা নির্ণয় করো।',f'Pইন = ρQgH = {fmt(pin)} W। Pবৈদ্যুতিক = 0.80Pইন = {fmt(pout)} W।',
       'প্রদত্ত সময়ে বৈদ্যুতিক শক্তি ও ক্ষয় নির্ণয় করে উৎসের শক্তি ব্যাখ্যা করো।',f'Eবৈদ্যুতিক = {fmt(pout*t)} J। Eঅনুপযোগী = {fmt((pin-pout)*t)} J। মূল উৎস জলের মহাকর্ষীয় বিভবশক্তির হ্রাস; টারবাইন/জেনারেটর নতুন শক্তি সৃষ্টি করে না।',dict(flow=flow,rho=rho,H=H,g=g,percent=80,t=t))

